-- Align the original starter migration with the production-oriented Prisma schema.
ALTER TABLE "User" ADD COLUMN IF NOT EXISTS "fullName" TEXT;
ALTER TABLE "Doctor" ADD COLUMN IF NOT EXISTS "city" TEXT, ADD COLUMN IF NOT EXISTS "latitude" DOUBLE PRECISION, ADD COLUMN IF NOT EXISTS "longitude" DOUBLE PRECISION, ADD COLUMN IF NOT EXISTS "geoRadiusMeters" INTEGER NOT NULL DEFAULT 250;
ALTER TABLE "Visit" ADD COLUMN IF NOT EXISTS "checkInAt" TIMESTAMP(3), ADD COLUMN IF NOT EXISTS "checkOutAt" TIMESTAMP(3), ADD COLUMN IF NOT EXISTS "checkInLat" DOUBLE PRECISION, ADD COLUMN IF NOT EXISTS "checkInLng" DOUBLE PRECISION, ADD COLUMN IF NOT EXISTS "checkOutLat" DOUBLE PRECISION, ADD COLUMN IF NOT EXISTS "checkOutLng" DOUBLE PRECISION, ADD COLUMN IF NOT EXISTS "productsDiscussed" TEXT, ADD COLUMN IF NOT EXISTS "doctorFeedback" TEXT, ADD COLUMN IF NOT EXISTS "consentVersion" TEXT, ADD COLUMN IF NOT EXISTS "consentCapturedAt" TIMESTAMP(3), ADD COLUMN IF NOT EXISTS "geoVerified" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "Product" ADD COLUMN IF NOT EXISTS "imageUrl" TEXT;
ALTER TABLE "Order" ADD COLUMN IF NOT EXISTS "cancelReason" TEXT, ADD COLUMN IF NOT EXISTS "cancelledAt" TIMESTAMP(3), ADD COLUMN IF NOT EXISTS "signatureName" TEXT, ADD COLUMN IF NOT EXISTS "signedAt" TIMESTAMP(3);
ALTER TABLE "Sample" ADD COLUMN IF NOT EXISTS "doctorId" INTEGER, ADD COLUMN IF NOT EXISTS "batchNumber" TEXT, ADD COLUMN IF NOT EXISTS "expiryDate" TIMESTAMP(3);
ALTER TABLE "Territory" ADD COLUMN IF NOT EXISTS "assignedToEmail" TEXT, ADD COLUMN IF NOT EXISTS "coverageTarget" INTEGER NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS "PasswordResetToken" ("id" SERIAL PRIMARY KEY, "email" TEXT NOT NULL, "code" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "usedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "Notification" ("id" SERIAL PRIMARY KEY, "channel" TEXT NOT NULL, "recipient" TEXT NOT NULL, "subject" TEXT NOT NULL, "body" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'queued', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
DO $$ BEGIN ALTER TABLE "Sample" ADD CONSTRAINT "Sample_doctorId_fkey" FOREIGN KEY ("doctorId") REFERENCES "Doctor"("id") ON DELETE SET NULL ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
